-- Central service schema. Portable ANSI SQL: it must apply unchanged on SQLite (tests) and Postgres (deployment).
-- Ids are text generated by the service; times are ISO-8601 UTC text; flags are 0/1 integers; JSON bodies are text.
-- Every statement is idempotent (CREATE TABLE IF NOT EXISTS), so applying the file twice changes nothing.
-- A column added after its table first shipped is also listed in db.COLUMNS_ADDED, so init-db adds it to an
-- existing database (CREATE TABLE IF NOT EXISTS leaves an existing table as it was).

CREATE TABLE IF NOT EXISTS account (
    id VARCHAR(64) PRIMARY KEY,
    email VARCHAR(320) NOT NULL UNIQUE,
    password_hash VARCHAR(512) NOT NULL,
    role VARCHAR(16) NOT NULL DEFAULT 'user',
    disabled INTEGER NOT NULL DEFAULT 0,
    failed_count INTEGER NOT NULL DEFAULT 0,
    locked_until VARCHAR(32),
    created_at VARCHAR(32) NOT NULL
);

CREATE TABLE IF NOT EXISTS session (
    id_hash VARCHAR(64) PRIMARY KEY,
    account_id VARCHAR(64) NOT NULL REFERENCES account (id) ON DELETE CASCADE,
    csrf_token VARCHAR(128) NOT NULL,
    created_at VARCHAR(32) NOT NULL,
    last_seen_at VARCHAR(32) NOT NULL
);

CREATE TABLE IF NOT EXISTS project (
    id VARCHAR(64) PRIMARY KEY,
    slug VARCHAR(64) NOT NULL UNIQUE,
    name VARCHAR(200) NOT NULL,
    repo_url VARCHAR(500),
    created_at VARCHAR(32) NOT NULL
);

CREATE TABLE IF NOT EXISTS member (
    project_id VARCHAR(64) NOT NULL REFERENCES project (id) ON DELETE CASCADE,
    account_id VARCHAR(64) NOT NULL REFERENCES account (id) ON DELETE CASCADE,
    role VARCHAR(16) NOT NULL,
    created_at VARCHAR(32) NOT NULL,
    PRIMARY KEY (project_id, account_id)
);

CREATE TABLE IF NOT EXISTS token (
    id VARCHAR(64) PRIMARY KEY,
    project_id VARCHAR(64) NOT NULL REFERENCES project (id) ON DELETE CASCADE,
    token_hash VARCHAR(64) NOT NULL UNIQUE,
    prefix VARCHAR(16) NOT NULL,
    scopes VARCHAR(64) NOT NULL,
    created_by VARCHAR(64) REFERENCES account (id),
    created_at VARCHAR(32) NOT NULL,
    revoked_at VARCHAR(32)
);

CREATE TABLE IF NOT EXISTS event (
    id VARCHAR(128) PRIMARY KEY,
    project_id VARCHAR(64) NOT NULL REFERENCES project (id) ON DELETE CASCADE,
    type VARCHAR(32) NOT NULL,
    ts VARCHAR(40),
    body TEXT NOT NULL,
    body_hash VARCHAR(64) NOT NULL,
    received_at VARCHAR(32) NOT NULL
);

CREATE TABLE IF NOT EXISTS task (
    id VARCHAR(64) PRIMARY KEY,
    project_id VARCHAR(64) NOT NULL REFERENCES project (id) ON DELETE CASCADE,
    item VARCHAR(64) NOT NULL,
    title VARCHAR(500),
    status VARCHAR(32),
    updated_at VARCHAR(32) NOT NULL,
    UNIQUE (project_id, item)
);

CREATE TABLE IF NOT EXISTS plan (
    id VARCHAR(64) PRIMARY KEY,
    project_id VARCHAR(64) NOT NULL REFERENCES project (id) ON DELETE CASCADE,
    task_id VARCHAR(64) REFERENCES task (id) ON DELETE CASCADE,
    body TEXT NOT NULL,
    created_at VARCHAR(32) NOT NULL
);

CREATE TABLE IF NOT EXISTS blocker (
    id VARCHAR(64) PRIMARY KEY,
    project_id VARCHAR(64) NOT NULL REFERENCES project (id) ON DELETE CASCADE,
    task_id VARCHAR(64) REFERENCES task (id) ON DELETE SET NULL,
    blocker_id VARCHAR(64) NOT NULL,
    question TEXT,
    body TEXT NOT NULL,
    status VARCHAR(32) NOT NULL,
    created_at VARCHAR(32) NOT NULL,
    updated_at VARCHAR(32) NOT NULL,
    UNIQUE (project_id, blocker_id)
);

CREATE TABLE IF NOT EXISTS decision (
    id VARCHAR(64) PRIMARY KEY,
    blocker_ref VARCHAR(64) NOT NULL REFERENCES blocker (id) ON DELETE CASCADE,
    version INTEGER NOT NULL,
    account_id VARCHAR(64) REFERENCES account (id),
    option_label VARCHAR(500),
    text TEXT,
    body TEXT NOT NULL,
    created_at VARCHAR(32) NOT NULL,
    UNIQUE (blocker_ref, version)
);

CREATE TABLE IF NOT EXISTS delivery (
    id VARCHAR(64) PRIMARY KEY,
    project_id VARCHAR(64) NOT NULL REFERENCES project (id) ON DELETE CASCADE,
    decision_id VARCHAR(64) NOT NULL REFERENCES decision (id) ON DELETE CASCADE,
    delivery_id VARCHAR(128) NOT NULL,
    status VARCHAR(16) NOT NULL,
    attempts INTEGER NOT NULL DEFAULT 0,
    last_error TEXT,
    created_at VARCHAR(32) NOT NULL,
    delivered_at VARCHAR(32),
    acked_at VARCHAR(32),
    UNIQUE (project_id, delivery_id)
);

CREATE TABLE IF NOT EXISTS issue (
    id VARCHAR(64) PRIMARY KEY,
    project_id VARCHAR(64) NOT NULL REFERENCES project (id) ON DELETE CASCADE,
    task_id VARCHAR(64) REFERENCES task (id) ON DELETE SET NULL,
    title VARCHAR(500) NOT NULL,
    body TEXT,
    status VARCHAR(32) NOT NULL,
    created_at VARCHAR(32) NOT NULL
);

CREATE TABLE IF NOT EXISTS audit (
    id VARCHAR(64) PRIMARY KEY,
    at VARCHAR(32) NOT NULL,
    account_id VARCHAR(64) REFERENCES account (id) ON DELETE SET NULL,
    project_id VARCHAR(64) REFERENCES project (id) ON DELETE SET NULL,
    action VARCHAR(64) NOT NULL,
    detail TEXT
);
